INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (5, 'garcia-jimenez-jose-alberto', 'Garcia Jiménez José Alberto', NULL, 1, '{"biography":"Ingeniero Mecánico Electricista, egresado de la Universidad de Colima, especializado en el área eléctrica y con experiencia profesional en el desarrollo de proyectos y obras eléctricas industriales. Cuenta con la certificación ACP (Autodesk Certified Professional), fortaleciendo su perfil en el uso de herramientas especializadas para el diseño y desarrollo de proyectos. Su experiencia se concentra en el diseño, planeación, ejecución y construcción de instalaciones eléctricas, así como en la aplicación práctica de la NOM-001-SEDE-2012, orientada al cumplimiento de los criterios técnicos y de seguridad aplicables a las instalaciones eléctricas. Como parte de su enfoque profesional, destaca su interés por la enseñanza basada en casos prácticos, utilizando la resolución de problemas reales como herramienta para transmitir conocimientos y desarrollar criterios técnicos aplicables al ejercicio de la ingeniería. Su metodología busca conectar los fundamentos teóricos con las situaciones que se presentan cotidianamente en el diseño, supervisión y construcción de instalaciones eléctricas."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (6, 'sierra-andrade-david-alejandro-cortes-lugo-hugo', 'Sierra Andrade David Alejandro / Cortes Lugo Hugo', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (7, 'benavides-sanchez-luis-daniel', 'Benavides Sánchez Luis Daniel', NULL, 1, '{"biography":"Maestro de inglés de la Universidad de Colima, adscrito a la Facultad de Ingeniería Mecánica y Eléctrica desde el año 2000 Escuela: Facultad de Lenguas Extranjeras, Universidad de Colima Licenciatura en Lengua Inglesa Certificaciones: FCE First Certificate of English Cambridge CAE Certificate of Advance English Cambrige COTE Certificate for Overseas Teachers of English"}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (8, 'martinez-sanchez-gregorio-josue', 'Martinez Sánchez Gregorio Josué', NULL, 1, '{"biography":"Doctor en Ingeniería Mecánica por la Universidad Nacional Autónoma de México (UNAM), con especialidad en biomecánica, mecánica de fluidos, dinámica de fluidos computacional (CFD) y diseño mecánico. Cuenta con experiencia en docencia universitaria, investigación y desarrollo de proyectos de ingeniería, integrando herramientas de modelado matemático, simulación numérica, diseño asistido por computadora y manufactura. Su trabajo de investigación se ha orientado al estudio de flujos biológicos y sistemas biomecánicos, con aplicaciones en los ámbitos ocular y cardiovascular, empleando plataformas de simulación como ANSYS y OpenFOAM. Asimismo, ha participado en el desarrollo y asesoría de proyectos de diseño mecánico, mecatrónica, movilidad eléctrica y desarrollo tecnológico, promoviendo la vinculación entre la investigación científica, la formación de estudiantes y la solución de problemas de ingeniería. Actualmente, su  línea de generación y aplicación del conocimiento  se centra en ingeniería de procesos biológicos, con énfasis en modelado computacional, biomecánica y dinámica de fluidos biológicos."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (9, 'ochoa-zuniga-oscar-octavio', 'Ochoa Zúñiga Oscar Octavio', NULL, 1, '{"biography":"Bachelor''s Degree in English Language. Area(s) of expertise: English. Professional and/or teaching experience: I have been working for the University of Colima for 21 years. Projects led: I have participated in several academic events at both the Faculty of Chemical Sciences and FIME. To name a few, I have led reading comprehension workshops at events such as TecnoFIME (2024 and 2025), and I have served as an abstract reviewer for projects during Chemist Week at the Faculty of Chemical Sciences."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (10, 'santillan-mendez-tomas', 'Santillán Méndez Tomás', NULL, 1, '{"biography":"Maestro en Ingeniería. 25 años como docente  Experiencia en proyectos eléctricos y obra eléctrica  En la industria, hoteles, escuelas, casa habitación."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (11, 'carrillo-avila-blanca-lorena', 'Carrillo Avila Blanca Lorena', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (12, 'galvez-martell-alicia-armantina', 'Galvez Martell Alicia Armantina', NULL, 1, '{"biography":"Profesora de la Universidad de Colima, institución en la que ha ejercido la docencia durante los últimos 24 años. Actualmente imparte cursos en la Facultad de Ingeniería Mecánica y Eléctrica y en la Facultad de Arquitectura y Diseño. Es egresada de la Facultad de Lenguas Extranjeras de la Universidad de Colima y ha complementado su formación académica con estudios en VanWest College (Canadá), Collin College (Estados Unidos) y la Universidad Nacional Autónoma de México (UNAM), campus San Antonio, Texas (Estados Unidos). Su trayectoria se ha enfocado en la enseñanza del idioma inglés en el ámbito de la educación superior, contribuyendo a la formación integral de estudiantes de diversas disciplinas."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (13, 'montejo-que-marco', 'Montejo Que Marco', NULL, 1, '{"biography":"Ingeniero en Comunicaciones y Electrónica, Maestro en Educación y una especialidad en enseñanza de las matemáticas y con una experiencia de 18 años dentro de la docencia a nivel  medio superior y superior."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (14, 'escobar-del-pozo-carlos', 'Escobar del Pozo Carlos', NULL, 1, '{"biography":"Profesor-Investigador Mexicano de la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima. Realizó sus estudios de doctorado en la Universidad Nacional Autónoma de México, en la Facultad de Ingeniería (2004-2008). En la misma Facultad realizó la Maestría en Ingeniería, 2002-2004, y obtuvo el título de Ingeniero Mecánico (1998-2002). En 2015 realizó un año sabático en el Departamento de Bioingeniería del Imperial College London, Reino Unido. Es miembro del Sistema Nacional de Investigadores nivel I. Carlos es especialista en el área de mecánica de fluidos y fenómenos de transporte. Su investigación se centra en el estudio de problemas biomédicos, en particular flujo sanguíneo y flujo en el ojo mediante el modelado matemático y simulación numérica. Ha publicado 26 artículos de investigación, tres capítulos de libro y 2 patentes. Es coordinador del programa de Maestría en Ingeniería de Procesos donde ha dirigido y colaborado en diversos proyectos, entre los cuales destacan la modelación matemática del crecimiento de aterosclerosis en arterias coronarias y simulación numérica en aneurismas. Actualmente, desarrolla proyectos de innovación, en particular el proyecto ArterioLab siendo finalista en el Premio Santander X México 2022, terna final en StartupBuilding by UAG,segundo lugar en Santander X México 2023, y seleccionado para la aceleradora de INCIDE Booster en 2025."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (15, 'diaz-alvarez-juan-pablo-martinez-camarena-sonia', 'Diaz Álvarez Juan Pablo / Martinez Camarena Sonia', NULL, 1, '{"biography":null}');
