INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (17, 'velazquez-gonzalez-cruz-ernesto', 'Velázquez González Cruz Ernesto', NULL, 1, '{"biography":"Ingeniero Civil. Área de especialidad: Matemáticas, Física, Estadística, dibujo Experiencia profesional: Ingeniero constructor,  subdirector de obras en la comisión del agua de Tecomán  y docente desde 2008."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (18, 'mata-lopez-walter-alexander', 'Mata López Walter Alexander', NULL, 1, '{"biography":"Profesor-Investigador de Tiempo Completo"}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (19, 'cerrato-abdala-brenda', 'Cerrato Abdalá Brenda', NULL, 1, '{"biography":"Egresada de la Maestría en Tecnologías de la Información, de la Facultad de Telemática de la Universidad de Colima e Ingeniera en Sistemas Computacionales por parte del Instituto Tecnológico de Colima. Encargada del Centro de Cómputo de FIME, turno matutino. Profesora por horas con más de 10 años de experiencia en los programas de Ingeniería en Mecatrónica e Ingeniería en Cómputo Inteligente, especializada principalmente en conocimientos relacionados con algorítmica, programación, desarrollo de proyectos integradores y manejo de la placa de proyectos Arduino."}');
