INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (23, 'navarro-marquez-gabriel', 'Navarro Márquez Gabriel', NULL, 1, '{"biography":"Cuenta con formación de posgrado en Ciencias Administrativas, y Recursos Humanos, complementada con estudios y actualización profesional en áreas relacionadas con la gestión organizacional, educación, tecnologías y responsabilidad social. Sus principales áreas de especialidad comprenden la gestión de recursos humanos, la administración y la gestión institucional, la formación y la capacitación, la evaluación y la mejora continua, la responsabilidad social, así como la planeación y la gestión de proyectos académicos. Asimismo, cuenta con experiencia en procesos de evaluación institucional y sistematización de información para la toma de decisiones. Cuenta con amplia experiencia en el ámbito universitario, desempeñándose en funciones de gestión académica, administrativa y directiva, así como en la coordinación de proyectos institucionales. Ha ejercido funciones directivas en educación media superior y actualmente participa en actividades de gestión y administración en el Centro Universitario de Investigaciones Jurídicas de la Universidad de Colima.  Su experiencia docente se vincula con la formación profesional y el desarrollo de competencias en áreas de gestión, recursos humanos y organizaciones, combinando la práctica institucional con la formación académica."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (24, 'nmg-cabl-pjm-bgag-mcs-dajp', 'NMG / CABL / PJM / BGAG / MCS / DAJP', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (25, 'barragan-gonzalez-angel-gabriel', 'Barragán González Ángel Gabriel', NULL, 1, '{"biography":"Ingeniero en Sistemas Electrónicos y Telecomunicaciones por la Universidad de Colima. Durante su formación académica ha participado en proyectos prácticos relacionados con el diseño y análisis de circuitos electrónicos, programación de microcontroladores y sistemas de control. Cuenta con conocimientos en electrónica, telecomunicaciones, automatización industrial y programación, con especial interés en el diseño de circuitos electrónicos, electrónica de potencia y desarrollo de sistemas embebidos. Su formación le ha permitido desarrollar habilidades para la resolución de problemas técnicos y el trabajo en equipo."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (26, 'contreras-aguilar-luis-alberto', 'Contreras Aguilar Luis Alberto', NULL, 1, '{"biography":"Doctor por la UMSNH 2011. Áreas de especialidad: Sistemas eléctricos de potencia Proyectos dirigidos o en los que ha participado. Entre los proyectos documentados se encuentran: Análisis en Estado Estable y Dinámico de Enlaces Asíncronos basados en el Transformador de Frecuencia Variable, financiado por CONACYT. Análisis Armónico y de Estabilidad Paramétrica en Sistemas Eléctricos con Generación Eólica y dispositivos FACTS, con apoyo de PRODEP. Investigación relacionada con sistemas fotovoltaicos interconectados y flujos de potencia en redes de distribución. Trabajos sobre estabilidad transitoria de parques eólicos, análisis de oscilaciones de baja frecuencia y modelado de generadores eólicos y STATCOM. Líneas de Generación y Aplicación del Conocimiento (LGAC).En el Cuerpo Académico UCOL-CA48 “Sistemas Eléctricos de Potencia”, en el que aparece como integrante, se reportaron las LGAC: Análisis y diseño de sistemas eléctricos de potencia. Calidad y uso eficiente de la energía."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (27, 'alcaraz-valencia-pablo-armando', 'Alcaraz Valencia Pablo Armando', NULL, 1, '{"biography":"Doctor en Tecnologías de la Información por la Universidad de Guadalajara. Profesor de Tiempo Completo. Mi labor se enfoca en integrar hardware y software para mejorar la gestión de información análogo-digital en sectores educativos, asistenciales, de ingeniería y biotecnología. Desarrollo y analizo tecnología educativa y social, dispositivos inteligentes y soluciones mecatrónicas orientadas a la eficiencia, la accesibilidad y el bienestar. Mi objetivo profesional es impulsar avances tecnológicos inclusivos, que apoyen la salud, fortalezcan los procesos formativos y optimicen la operación industrial mediante herramientas innovadoras con impacto social."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (28, 'villalobos-llamas-gilberto', 'Villalobos Llamas Gilberto', NULL, 1, '{"biography":"Doctor en Ingeniería Mecánica Área(s) de especialidad: Mecánica de materiales, diseño mecánico. Experiencia profesional y/o docente: 28 años de antigüedad, impartiendo materias de Dinámica, Diseño de elementos de máquinas, mecánica de materiales I y II Proyectos dirigidos: Diseño mecánico Líneas de generación y aplicación del conocimiento [LGAC]: Responsable del cuerpo académico UCOL 125 mecánica y materiales, líneas de Investigación: Diseño de máquinas y mecánica teórica."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (29, 'cardenas-rodriguez-selene', 'Cardenas Rodriguez Selene', NULL, 1, '{"biography":"La Dra. Selene Cárdenas Rodríguez es Doctora en Educación por la Universidad de Baja California, Maestra en Ingeniería con área de especialidad en Estructuras e Ingeniera Civil por la Universidad de Colima. Cuenta con más de doce años de experiencia como docente universitaria, formando estudiantes de Ingeniería Civil, Ingeniería Mecánica Electricista y Mecatrónica en la Universidad de Colima, además de haber impartido docencia en el Instituto Tecnológico de Colima. Ha impartido asignaturas de ciencias básicas, ingeniería estructural y formación profesional, entre ellas Álgebra Lineal, Cálculo, Ecuaciones Diferenciales, Estática, Resistencia de Materiales, Mecánica de Materiales, Física, Dibujo en Ingeniería, Tecnología de los Materiales y Estructuras Isostáticas. Su trayectoria integra la ingeniería estructural con la educación superior, orientando su práctica docente hacia la innovación educativa, la evaluación del aprendizaje, el desarrollo de competencias profesionales y la formación integral de futuros ingenieros. Ha participado en proyectos de investigación y en la elaboración y presentación de publicaciones científicas en el área de ingeniería estructural, así como en actividades de vinculación y divulgación académica. Asimismo, ha impulsado iniciativas de comunicación institucional y difusión de la ingeniería, siendo responsable durante una década de la gestión de contenidos de FIMEVENTOS, promoviendo la visibilidad de las actividades académicas, científicas y estudiantiles de la Facultad. Concibe la docencia como una oportunidad para formar profesionistas con sólidos fundamentos científicos y técnicos, pensamiento crítico, responsabilidad social y compromiso ético, convencida de que la excelencia académica se construye no solo a través del dominio disciplinar, sino también mediante el acompañamiento, la formación integral y el compromiso con el crecimiento de cada estudiante. Grado académico  Doctora en Educación.  Maestra en Ingeniería (Área de Estructuras).  Ingeniera Civil. Áreas de especialidad  Ingeniería estructural.  Mecánica de materiales y análisis estructural.  Educación en ingeniería.  Evaluación del aprendizaje.  Innovación educativa. Experiencia profesional y docente Más de doce años de experiencia como profesora por asignatura en la Universidad de Colima y experiencia docente en el Instituto Tecnológico de Colima, impartiendo asignaturas de ciencias básicas, estructuras e ingeniería aplicada en los programas educativos de Ingeniería Civil, Ingeniería Mecánica Electricista, Ingeniería en Computación Inteligente e Ingeniería en Mecatrónica. Proyectos dirigidos: Organización y coordinación de actividades académicas y de vinculación universitaria. Difusión institucional y comunicación de proyectos académicos mediante FIMEVENTOS. Participación en proyectos de investigación y publicaciones científicas en ingeniería estructural. LGAC Educación en ingeniería e innovación educativa. Ingeniería estructural y análisis sísmico de estructuras. Diseño sísmico basado en desempeño y confiabilidad estructural. Evaluación del aprendizaje y formación integral de ingenieros."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (30, 'mora-quinones-jesus-uriel', 'Mora Quiñones Jesús Uriel', NULL, 1, '{"biography":"Maestro en Ingeniería, pasante de Doctorado en Ingeniería para la Innovación Tecnológica, área de especialización en diseño de electrónica digital, imparte clases de electrónica analógica, electrónica digital, ética, circuitos eléctricos y electrónicos, diseño de experimentos, instrumentación virtual, programación avanzada, dibujo en ingeniería, entre otras."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (31, 'jardines-gonzalez-arturo-ivan', 'Jardines González Arturo Iván', NULL, 1, '{"biography":"Egresado de la Universidad de Colima como Ingeniero Mecánico Electricista y cuenta con Maestría y Doctorado en Ciencias en Ingeniería Eléctrica por el Instituto Tecnológico de Morelia. A lo largo de su trayectoria se ha especializado en el estudio de transitorios electromagnéticos ultrarrápidos y sistemas de puesta a tierra, campo en el que sus investigaciones sobre el impacto en transformadores han sido citadas internacionalmente. Su labor combina la docencia y el diseño académico con la capacitación especializada técnica a ingenieros de la CFE y el desarrollo práctico de proyectos de ingeniería eléctrica para los sectores público y privado dentro y fuera de la región."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (32, 'bricio-chapula-carlos-adrian', 'Bricio Chapula Carlos Adrián', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (33, 'arroyo-ledesma-jaime', 'Arroyo Ledesma Jaime', NULL, 1, '{"biography":"Dr. en Ciencias en Ingeniería Eléctrica Área de especialidad. Sistemas eléctricos de potencia. Experiencia profesional y/o docente. 20 años como PTC en la UCol. Proyectos dirigidos Análisis bilineal de sistemas eléctricos. Líneas de generación y aplicación del conocimiento [LGAC]. Análisis y Diseño de Sistemas Eléctricos de Potencia."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (34, 'ramirez-arceo-guillermo-alejandro', 'Ramírez Arceo Guillermo Alejandro', NULL, 1, '{"biography":"Doctor en Ingeniería Eléctrica y Electrónica por la Universidad Autónoma de Tamaulipas, grado obtenido en 2022. Su trayectoria académica incluye una Maestría en Ingeniería de Procesos por la Universidad de Colima, un Máster Universitario en Ingeniería Matemática por la Universidad Carlos III de Madrid y la Licenciatura en Matemáticas por la Universidad de Colima. Su área de especialidad se centra en las ciencias físico matemáticas, específicamente en el análisis y análisis funcional con un enfoque en matemáticas aplicadas. Se ha especializado en el estudio de las propiedades algebraicas y analíticas de los polinomios ortogonales y su implementación en diversas áreas de la ingeniería. En cuanto a su experiencia profesional y docente, actualmente se desempeña como investigador posdoctoral y profesor por horas en la Universidad de Colima. Previamente, realizó una estancia posdoctoral en el Tecnológico de Monterrey y fue profesor en el Instituto Tecnológico de Colima y en la Universidad Carlos III de Madrid. Ha impartido cátedras de álgebra lineal, cálculo diferencial e integral, estadística, métodos numéricos, vibraciones mecánicas y semanarios de tesis e investigación. Además, cuenta con experiencia en la dirección de tesis de maestría y doctorado en temas de control robusto. Sus líneas de generación y aplicación del conocimiento se enfocan en: Estudio de propiedades algebraicas y analíticas de polinomios ortogonales con aplicaciones a bioprocesos, Diseño robusto de sistemas lineales de control, incluyendo técnicas de asignación de polos y sintonización de controladores PID, Desarrollo de clasificadores basados en máquinas de soporte vectorial (SVM) y funciones kernel para la clasificación de patrones y aplicaciones tecnológicas en sistemas steer-by-wire de vehículos autónomos y biosensores."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (35, 'diaz-hernandez-juan-antonio', 'Diaz Hernández Juan Antonio', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (36, 'nava-bautista-martha-xochitl', 'Nava Bautista Martha Xóchitl', NULL, 1, '{"biography":"Ingeniera Telemática por la Universidad de Colima, Maestra en Seguridad Informática por UNIR, además de Diploma de Estudios Avanzados (Universidad de Vigo) y Maestría en Gestión de las Tecnologías de Información (Universidad Ramón Llull).  Certificada como Auditora Interna ISO 27001:2022 e instructora de Cisco Networking Academy, cuenta con una amplia trayectoria docente e institucional impartiendo asignaturas de matemáticas, redes, seguridad de la información, análisis de sistemas y programación. Actualmente es responsable del Laboratorio de Telefonía y presidenta de la Academia de ICI. Ha fungido como asesora de tesis, tutora grupal y fue reconocida como Mejor Docente en 2016. Ha participado en la elaboración y evaluación de reactivos del EGEL y su trabajo de investigación vincula la tecnología con el área de la salud."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (37, 'gonzalez-zepeda-sebastian', 'González Zepeda Sebastián', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (38, 'felix-cuadras-ramon-antonio', 'Félix Cuadras Ramón Antonio', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (39, 'maciel-barboza-fermin-marcelo-ruben', 'Maciel Barboza Fermín Marcelo Rubén', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (40, 'regalado-escobedo-alejandro', 'Regalado Escobedo Alejandro', NULL, 1, '{"biography":"Ingeniero en Comunicaciones y Electrónica y la Maestría en Computación, con especialidad en Control Asistido por Computadora. Se especializa en las áreas de instrumentación industrial, programación de microcontroladores, automatización de procesos industriales y diseño electrónico y de circuitos impresos. Cuenta con una experiencia de 22 años como Docente por Asignatura. Ha dirigido tesis de nivel licenciatura en áreas ya mencionadas y ha participado en el diseño y ejecución de Proyectos integradores por semestre en la carrera de ISET y Mecatrónica. Las líneas de generación y aplicación del conocimiento en las que se desarrolla son las de instrumentación electrónica, energías renovables, automatización de procesos industriales y diseño electrónico."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (41, 'perez-perez-zhared', 'Pérez Pérez Zhared', NULL, 1, '{"biography":"Doctora en Investigación con enfoque educativo. Se ha desempeñado como docente de diversos cursos en nivel licenciatura y bachillerato. Sus líneas de investigación versan en los estudios de jóvenes, ciencias sociales, valores y cultura cívica. Ha participado en grupos de investigación, incluyendo proyectos financiados por la Universidad de Colima como el de “La Cultura política de jóvenes estudiantes en Colima” (2023-2024), “¿Humanidades para qué? Fomento de las vocaciones científicas en jóvenes de educación media superior” (2023-2024), el proyecto de “Análisis interdisciplinario del riesgo psicosocial de las personas trabajadoras de la Universidad de Colima, en el marco de la ética profesional, los derechos humanos y la NOM -035-STPS-2018: Un acercamiento para la dignidad laboral” (2024-2025), y los \"Modelos de intervención educativa, estrategias de intervención, y formación docente para la atención de la inclusión educativa y la interculturalidad\" (2025). Actualmente, participa en el proyecto “Imaginarios sociales de adolescentes en contextos de violencia e incertidumbre. De la memoria a la construcción de futuros de paz\" (2025-2026) y en la investigación “La incorporación de la inteligencia artificial en las clases de educación media superior y licenciatura de la Universidad de Colima” (2025-2026)."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (42, 'nmg-ppz-mbfmr-rea-mcs-mqju-fcra', 'NMG / PPZ / MBFMR / REA / MCS / MQJU / FCRA', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (43, 'lopez-barajas-gabriel', 'López Barajas Gabriel', NULL, 1, '{"biography":"Ingeniero Mecánico Electricista y Maestro en Ingeniería de Procesos por la Universidad de Colima. Se desempeña como profesor de la Facultad de Ingeniería Mecánica y Eléctrica (FIME) y responsable del Laboratorio de Mecánica, donde participa en actividades de docencia, desarrollo de proyectos y formación práctica de estudiantes. Su experiencia académica comprende las áreas de termodinámica, termofluidos, mecánica de fluidos, transferencia de calor, sistemas hidráulicos y neumáticos, eficiencia energética y diseño mecánico. Sus principales áreas de interés se centran en el diseño y análisis de sistemas mecánicos, modelado y simulación numérica mediante FEM y CFD, así como en aplicaciones de termofluidos y bioingeniería, vinculando estas herramientas con el desarrollo y solución de problemas reales de ingeniería."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (44, 'llamas-zamorano-sergio', 'Llamas Zamorano Sergio', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (45, 'ramirez-zuniga-diego-armando', 'Ramírez Zúñiga Diego Armando', NULL, 1, '{"biography":"Maestro en Ingeniería Aplicada, con formación en Ingeniería en Mecatrónica. Con experiencia como profesor por horas en las asignaturas de Análisis de Mecanismos, Sistemas Automatizados, Dibujo Técnico y Ética Profesional. Además, experiencia en el desarrollo y mantenimiento de sistemas técnicos mecánicos y eléctricos, programación de PLC, dibujo asistido por computadora."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (46, 'diaz-alvarez-juan-pablo', 'Díaz Álvarez Juan Pablo', NULL, 1, '{"biography":"Maestro en Ingeniería Mecánica,  especializado en diseño mecánico. Profesor de FIME con 25 años."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (47, 'santillan-mata-tomas-adalberto', 'Santillán Mata Tomás Adalberto', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (48, 'carrillo-zepeda-oswaldo', 'Carrillo Zepeda Oswaldo', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (49, 'gaytan-lugo-laura-sanely', 'Gaytán Lugo Laura Sanely', NULL, 1, '{"biography":"Profesora e investigadora de tiempo completo en la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima. Es Doctora en Tecnologías de Información por la Universidad de Guadalajara. Su trabajo se especializa en la Interacción Humano-Computadora (IHC), el diseño de experiencia de usuario (UX), el desarrollo de juegos serios, las tecnologías aplicadas al aprendizaje colaborativo y la accesibilidad. Es miembro activo del Sistema Nacional de Investigadoras e Investigadores (SNII) y ejerce un rol clave como secretaria de la Asociación Mexicana de Interacción Humano-Computadora (AmexIHC), colaborando también activamente en comités internacionales como ACM SIGCHI en Latinoamérica."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (50, 'gonzalez-potes-apolinar', 'González Potes Apolinar', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (51, 'castillo-topete-victor-hugo', 'Castillo Topete Victor Hugo', NULL, 1, '{"biography":"Obtuvo su grado de doctor en el CICESE, B.C., México. Actualmente es profesor-investigador de tiempo completo en la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima, en el área de Ciencias de la Computación. Es miembro del Sistema Nacional de Investigadores en México y ha participado en diversas experiencias académico-científicas en las que plantea el uso de sistemas basados en el conocimiento para gestionar procesos de cambio en diversos dominios de aplicación. Además de haber dirigido varias tesis de licenciatura, maestría y doctorado, Víctor ha participado como autor, coautor y editor asociado en diversas revistas científicas. Asimismo, ha integrado comités, tanto editoriales como de distintos foros académicos y científicos."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (52, 'evangelista-salazar-martha-elizabeth', 'Evangelista Salazar Martha Elizabeth', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (53, 'verduzco-ramirez-jesus-alberto', 'Verduzco Ramirez Jesus Alberto', NULL, 1, '{"biography":"Ingeniero Electrónico en Computación y Maestro en Ciencias Computacionales por la FIME, Universidad de Colima. Cuenta con una especialidad en Informática, Sistemas y Comunicaciones por la Universidad Joseph Fourier y un Doctorado en Informática por el Instituto Nacional Politécnico de Grenoble, ambos en Francia. Con más de 33 años de experiencia docente, actualmente es profesor por asignatura en la carrera de Ingeniería en Computación Inteligente en la FIME. Distinguido con el Perfil Deseable PRODEP, es también Candidato a Investigador Nacional por el Sistema Nacional de Investigadoras e Investigadores (SNII). Sus líneas de interés e investigación se centran en:  el monitoreo de la calidad del agua en granjas acuícolas, la automatización de procesos aplicando agentes inteligentes, el cómputo de alto rendimiento y  la computación cuántica."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (54, 'soriano-equigua-leonel', 'Soriano Equigua Leonel', NULL, 1, '{"biography":"Doctor en Ciencias Áreade especialidad: Electrónica y Telecomunicaciones Experiencia profesional y/o docente: Profesor-investigador de tiempo completo, miembro del Sistema Nacional de Investigadoras e Investigadores (SNII) nivel I. Proyectos dirigidos (opcional) Líneas de generación y aplicación del conocimiento [LGAC]: Electrónica y tecnología de comunicaciones"}');
