INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (58, 'gomez-ramirez-juan-carlos', 'Gómez Ramírez Juan Carlos', NULL, 1, '{"biography":"Maestro en Liderazgo y Dirección de Centros Educativos por la Universidad Internacional de La Rioja (UNIR) y Licenciado en Pedagogía por la Universidad de Colima. Cuenta con experiencia en el ámbito académico y en la gestión de procesos educativos. Como docente, participa en la formación de estudiantes de ingeniería, promoviendo el desarrollo de competencias profesionales, el emprendimiento y habilidades blandas. Actualmente se desempeña como Coordinador Académico de la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima"}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (59, 'venegas-trujillo-tiberio', 'Venegas Trujillo Tiberio', NULL, 1, '{"biography":"Maestro en Ciencias Área(s) de especialidad: Sistemas Eléctricos de Potencia Experiencia profesional y/o docente: Gerente de Proyectos y materias de ingeniería eléctrica. Proyectos dirigidos: Simulación y modelado de sistemas eléctricos   Líneas de generación y aplicación del conocimiento [LGAC]: Análisis y diseño de sistemas de potencia y Calidad y uso eficiente de la energía."}');
