INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (62, 'moya-mendoza-miguel-angel', 'Moya Mendoza Miguel Angel', NULL, 1, '{"biography":"M. en I. Miguel Ángel Moya Mendoza. Profesor por horas tipo \"B\" en la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima. Encargado del Laboratorio de Robótica e Inteligencia Artificial (IA). Maestro en Ingeniería, enfocado en sistemas biomecánicos, bioingeniería, biomedicina y CFD por parte de la Universidad de Colima, Coquimatlán, México. Ingeniero Mecatrónico, con especialidad en Sistemas Autónomos Inteligentes y Mantenimiento Mecánico por el Tecnológico de Colima. Cuenta con experiencia en la industria, trabajó como Supervisor de mantenimiento mecánico en Peña Colorada (Peletizadora), Jefe de distribución en Nutricol de Colima, Coordinador de logística y distribución en Liconsa S.A. de C.V. Ha participado en proyectos de investigación alusivos al estudio y formación de aneurismas intracraneales mediante el uso de simulación numérica (CFD, Computational Fluid Dynamics) con softwares como Fusion 360, Openfoam y Ansys. Apoyo en diseño y fabricación de prótesis de pezuña para ganado bovino, y perros con extremidades amputadas. En conjunto con ingenieros expertos, ha proporcionado y generado documentación acerca de manuales para el mantenimiento mecánico de equipos como: bandas transportadoras, poleas y bombas en la peletizadora de Peña Colorada."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (63, 'bautista-quintero-victor-hugo', 'Bautista Quintero Victor Hugo', NULL, 1, '{"biography":null}');
