INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (70, 'guzman-vega-hector-gustavo', 'Guzmán Vega Héctor Gustavo', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (71, 'huizar-padilla-emilio', 'Huizar Padilla Emilio', NULL, 1, '{"biography":"Doctor en Ciencias Químicas y Licenciado en Física por la Universidad de Colima. Durante su formación académica fue reconocido en dos ocasiones con el Premio Peña Colorada, distinción estatal otorgada conjuntamente por el Consorcio Minero Benito Juárez Peña Colorada y la Universidad de Colima, al ser reconocido como mejor egresado tanto de la Licenciatura en Física como de sus estudios de posgrado. En 2010 se desempeñó como técnico programador en el Centro Universitario de Investigación en Ciencias del Ambiente de la Universidad de Colima, participando en actividades de apoyo técnico y computacional a la investigación. Desde 2011 es profesor en la Universidad de Colima y actualmente desarrolla su actividad docente en la Facultad de Ingeniería Mecánica y Eléctrica, donde imparte asignaturas de ciencias básicas y participa en el desarrollo y supervisión de proyectos integradores de Ingeniería en Mecatrónica. Su labor docente ha sido reconocida en diversas ocasiones entre los profesores mejor evaluados por sus estudiantes. Su trabajo de investigación se ha centrado en el estudio y modelado de sensores de gases basados en semiconductores de óxidos metálicos, particularmente en la comprensión de las interacciones entre los gases, la superficie y las propiedades eléctricas de los materiales sensores. Asimismo, ha ampliado su actividad hacia el desarrollo experimental de materiales y dispositivos, instrumentación científica, electrónica y sistemas de adquisición y control. Entre sus áreas de interés se encuentran la física del estado sólido, química teórica y computacional, materiales semiconductores, sensores, radiofrecuencia, sistemas embebidos y procesamiento de señales. Su trabajo busca integrar modelado, experimentación e instrumentación para desarrollar metodologías y dispositivos aplicables a investigación, docencia y tecnología."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (72, 'sada-cab-hpe-smta-bchg', 'SADA / CAB / HPE / SMTA / BCHG', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (73, 'valencia-valencia-elias-humberto', 'Valencia Valencia Elías Humberto', NULL, 1, '{"biography":"Grado académico: Especialidad Área de especialidad: Electrónica Analógica, Electrónica de Potencia, Microcontroladores. Experiencia profesional y/o docente: 25 años como docente impartiendo clases de electrónica."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (74, 'plascencia-manzo-imelda', 'Plascencia Manzo Imelda', NULL, 1, '{"biography":"Licenciada en Ciencias con Especialidad en Física, con Maestría en Ciencias de la Tierra en el área de sismología ambos en la Universidad de Colima y un diplomado en competencias docentes para la Educación Media Superior (DIFORDEMS). Las áreas de especialidad son en Matemáticas (Álgebra, geometría analítica, fundamentos de estadística y probabilidad, cálculo diferencial e integral, cálculo vectorial, álgebra lineal), además de Física para ingenierías y Nivel Medio Superior. Participación continua en proyectos con la Coordinación General de Vinculación de la Universidad de Colima desde el año 2009 a la fecha con estudios relacionados con monitoreos ambientales y evaluación de riesgos o peligros naturales y antropogénicos. Además de apoyo técnico en el monitoreo visual del Volcán de Colima en el Centro Universitario de Estudios Vulcanológicos (CUEIV). Y desde el 2024 apoyo técnico en el Museo “La Casa del Volcán” de la Universidad de Colima. Profesor de matemáticas (Probabilidad y Estadística y Matemáticas Aplicadas) en NMS en las carreras de Electricidad y Programación. Y apoyo de mentorías en el programa “Mujeres Líderes STEAM” en 2019. En investigación científica participación en 4 artículos publicados en revistas indexadas y un capítulo en el libro COMPLEX MONITORING OF VOLCANIC ACTIVITY. METHODS AND RESULTS, todas las publicaciones relacionadas con el Volcán de Colima."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (75, 'mcs-hpe-msgj-vveh-rmjm-ipm', 'MCS / HPE / MSGJ / VVEH / RMJM / IPM', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (76, 'rodriguez-monroy-jose-miguel', 'Rodriguez Monroy José Miguel', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (77, 'mcs-hpe-msgj-leit-vveh-ipm', 'MCS / HPE / MSGJ / LEIT / VVEH / IPM', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (78, 'ibarra-terrones-lourdes-edurnne', 'Ibarra Terrones Lourdes Edurnne', NULL, 1, '{"biography":"Licenciada en Contaduría y Maestra en Alta Dirección, con experiencia profesional en el área administrativa y financiera, particularmente en la gestión, planeación y control de recursos, seguimiento presupuestal y procesos administrativos institucionales. Cuenta con experiencia docente en educación superior, principalmente en la Ingeniería en Mecatrónica e Ingeniería Sistemas Electrónicos y Telecomunicaciones, donde ha impartido asignaturas relacionadas con administración, costos, contabilidad, economía y legislación, vinculando los conocimientos administrativos y financieros con la gestión y desarrollo de proyectos de ingeniería. Sus principales áreas de especialidad comprenden la gestión administrativa y financiera, planeación presupuestal, costos, evaluación de proyectos y toma de decisiones."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (79, 'toscano-cardenas-leticia-lizeth', 'Toscano Cárdenas Leticia Lizeth', NULL, 1, '{"biography":"Licenciada en Enseñanza de la Lengua Inglesa, egresada de la Universidad de Colima. Cuenta con la certificación internacional ICELT (In-Service Certificate in English Language Teaching), otorgada por el British Council, que acredita su formación especializada para la enseñanza del inglés como segunda lengua. Asimismo, a lo largo de su trayectoria profesional ha certificado periódicamente sus competencias lingüísticas mediante reconocidas certificaciones internacionales, entre ellas TOEFL iBT, IELTS y Cambridge English: Advanced (CAE), como parte de su compromiso con la actualización y el fortalecimiento continuo de sus competencias profesionales y lingüísticas. Área de especialidad: Enseñanza y aprendizaje de lenguas extranjeras, particularmente del idioma inglés, así como el desarrollo de competencias comunicativas en contextos educativos. Experiencia profesional y docente: Cuenta con 24 años de experiencia profesional en la Universidad de Colima, donde se ha desempeñado como docente de inglés y como responsable en la coordinación del Centro Especializado de Idiomas (CEI) Coquimatlán. Como parte de su trayectoria internacional, se desempeñó durante un año como docente de español en Robbinsdale Spanish Immersion School, en Mineapoli, MN. Estados Unidos, y colaboró también durante 6 meses, en una estancia académica en la University of Southampton, Inglaterra, fortaleciendo su experiencia en contextos educativos internacionales y multiculturales. Proyectos dirigidos: Ha participado en proyectos y actividades académicas orientadas al fortalecimiento de la enseñanza y aprendizaje de lenguas extranjeras, así como en la organización y coordinación de actividades formativas en el Centro Especializado de Idiomas. Líneas de generación y aplicación del conocimiento (LGAC): Enseñanza y aprendizaje de lenguas extranjeras y desarrollo de estrategias para el fortalecimiento de las competencias comunicativas en inglés."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (80, 'garcia-rebolledo-azael', 'García Rebolledo Azael', NULL, 1, '{"biography":"Doctor en Ingeniería   Área(s) de especialidad. Mecánica aplicada y experimental. Experiencia profesional y/o docente. Proyectos desarrollados para el área automotriz, 16 años experiencia docente. Proyectos dirigidos: Biomecánica aplicada experimental y numérica, asesoría de proyectos de robótica e Inteligencia aplicada en seguridad, agricultura y automotriz. Líneas de generación y aplicación del conocimiento [LGAC]: Biomecánica aplicada en dinámica de fluidos, diseño y construcción de dispositivos mecatrónicos en procesos innovadores."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (81, 'smta-jgal-lbg-tcca-vveh-agr', 'SMTA / JGAL / LBG / TCCA / VVEH / AGR', NULL, 1, '{"biography":null}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (82, 'torres-cantero-carlos-alberto', 'Torres Cantero Carlos Alberto', NULL, 1, '{"biography":"Doctor en Ciencias en Ingeniería Electrónica por el Centro Nacional de Investigación y Desarrollo Tecnológico (CENIDET) y miembro del Sistema Nacional de Investigadoras e Investigadores (SNII), Nivel 1. Actualmente se desempeña como Profesor-Investigador de Tiempo Completo en la Facultad de Ingeniería Mecánica y Eléctrica de la Universidad de Colima y cuenta con más de 20 años de experiencia docente en educación superior, además de experiencia profesional, de investigación y desarrollo tecnológico en control automático de procesos, automatización, instrumentación, sistemas embebidos, robótica, energías renovables, simulación de procesos e inteligencia computacional. Ha participado en el desarrollo y dirección de proyectos relacionados con la automatización y control de procesos para la producción de bioetanol y biohidrógeno, sistemas acuapónicos e hidropónicos automatizados, sistemas robóticos y plataformas de adquisición, monitoreo y supervisión mediante SCADA. Es miembro del Cuerpo Académico UCOL-CA-91 “Automatización y Sistemas Embebidos”, en consolidación, cuyas Líneas de Generación y Aplicación del Conocimiento (LGAC) son “Automatización, Instrumentación y Control” y “Sistemas Embebidos y Algoritmos Inteligentes”. Su actividad académica comprende además la formación de recursos humanos y la colaboración en proyectos de investigación y desarrollo tecnológico con instituciones nacionales e internacionales."}');
INSERT INTO professors (id, slug, full_name, email, delegation_id, profile_data) VALUES (83, 'rodriguez-barragan-irving-naim', 'Rodriguez Barragán Irving Naim', NULL, 1, '{"biography":null}');
